import{_ as o,o as u,c as r,ag as q}from"./chunks/framework.D5hoimZQ.js";const h=JSON.parse('{"title":"03 宏观经济与货币 —— 天涯神贴精读笔记","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/tianya/notes/03_宏观经济与货币.md","filePath":"topics/tianya/notes/03_宏观经济与货币.md"}'),a={name:"topics/tianya/notes/03_宏观经济与货币.md"};function n(s,t,e,g,p,l){return u(),r("div",null,[...t[0]||(t[0]=[q('<h1 id="_03-宏观经济与货币-——-天涯神贴精读笔记" tabindex="-1">03 宏观经济与货币 —— 天涯神贴精读笔记 <a class="header-anchor" href="#_03-宏观经济与货币-——-天涯神贴精读笔记" aria-label="Permalink to &quot;03 宏观经济与货币 —— 天涯神贴精读笔记&quot;">​</a></h1><blockquote><p>覆盖 12 个文件（其中两篇为图片版 PDF、无可提取正文，见第 2、6 节说明）。观点均摘自原文，预测对照以 2026 年为观察点。</p></blockquote><h2 id="_1-flp713《你所不知道的冰冷的经济真相》-2011-12" tabindex="-1">1. flp713《你所不知道的冰冷的经济真相》（2011.12） <a class="header-anchor" href="#_1-flp713《你所不知道的冰冷的经济真相》-2011-12" aria-label="Permalink to &quot;1. flp713《你所不知道的冰冷的经济真相》（2011.12）&quot;">​</a></h2><p><strong>核心论点</strong>：① 保 8 本质是就业与稳定——劳动供养率仅 1:1.1（美 1:4.8），1 亿劳动人口需 8000 万岗位；② 分配失衡是总根源：财税抽走 20%、垄断央企隐性掠夺 10%、印钞机再超发，剩不到 20% 归 80% 的人；③ 扭曲汇率+出口退税→外储暴涨→央行被动发钞→通胀由百姓买单；④ 货币蓄水池论：94–2000 池子是教育医疗住房市场化，2000–2011 是股市房市（股市还是&quot;蒸发财富的锅&quot;），2011 年后短期房市+股市、中期股市+土地、长期人民币国际化；⑤ 未来十年三大改革＝股改、汇改、土改；⑥ 中国还有黄金十年；⑦ 调控无用：根因是政府垄断供地与货币超发，调控后必报复性上涨。</p><p><strong>方法论</strong>：读中央文件倒推十年布局——&quot;现在发生的是前 10 年宏观布局决定的&quot;。 <strong>金句</strong>：在中国，保护财富比创造财富更重要；炒股票研究 K 线图还不如关注猪肉的价格走势。 <strong>预测对照</strong>：房价报复性上涨→准（2012–2021）；黄金十年→准；股市是锅→准（2015 股灾）；&quot;两位数 CPI 偷走财富&quot;→不准（官方 CPI 长期 2% 上下，2023 年后反成通缩压力）；宅基地释放数十万亿→部分准（确权完成、入市未放开）。</p><h2 id="_2-海宁《经济大周期-踩准节拍再投资》" tabindex="-1">2. 海宁《经济大周期：踩准节拍再投资》 <a class="header-anchor" href="#_2-海宁《经济大周期-踩准节拍再投资》" aria-label="Permalink to &quot;2. 海宁《经济大周期：踩准节拍再投资》&quot;">​</a></h2><p>该 PDF 为图片扫描版，无可提取正文（仅书商水印），无法精读原文，为不编造观点本节只记录元信息：海宁著，以经济周期与资产轮动为主题的出版书（约 2013–2014 年），与第三元、曼因斯坦的周期框架同源。</p><h2 id="_3-第三元《2013–2017-的大框架》-2013-5–2016-12" tabindex="-1">3. 第三元《2013–2017 的大框架》（2013.5–2016.12） <a class="header-anchor" href="#_3-第三元《2013–2017-的大框架》-2013-5–2016-12" aria-label="Permalink to &quot;3. 第三元《2013–2017 的大框架》（2013.5–2016.12）&quot;">​</a></h2><p><strong>核心论点</strong>：① 货币两阶段论：2002–2012&quot;名义升值、实际贬值&quot;（超发养资产与债务），2013 年起&quot;现实升值、名义贬值&quot;，全社会进入还债模式；② 全球贬值接力：日元→英镑→欧元→澳元相继贬值，人民币最后贬值，贬值反转之日即地产反转之时；③ 人民币之锚＝外贸+美元美债；④ 新蓄水池＝股市：&quot;IPO 发行之日，就是蓄水池正式启动之时&quot;，牛市先由银行股&quot;粮草先行&quot;，摒弃上轮疯牛股；⑤ 房价&quot;三五年的事&quot;，会在新政府第二届任期前解决；⑥ 后期转向长线价值投资，反创业板泡沫、反乐视式投机。</p><p><strong>方法论</strong>：把汇率、利率、资产价格排成先后次序看传导；以&quot;谁在还债、谁在接盘&quot;替代供需分析。 <strong>金句</strong>：人民币就是一个从悬崖底部往上爬的人，最终目的是爬上悬崖乘缆车下去；这世界上有 10% 的人有远见，其中只有 10% 有耐心践行。 <strong>预测对照</strong>：A 股牛市 2–3 年、上证 4000+→准（2015 年 5178）；人民币三年多内贬值→准（2015.8 汇改）；黄金跌向 1000→准（2015 年底 1050）；房价 2016–2018 下跌→不准（2016–17 暴涨，普跌 2021 年后才来，方向对、时点错三年以上）。</p><h2 id="_4-kulese《戏说牛市合适崩盘》-2015-5-发帖于-5178-点前两周" tabindex="-1">4. kulese《戏说牛市合适崩盘》（2015.5，发帖于 5178 点前两周） <a class="header-anchor" href="#_4-kulese《戏说牛市合适崩盘》-2015-5-发帖于-5178-点前两周" aria-label="Permalink to &quot;4. kulese《戏说牛市合适崩盘》（2015.5，发帖于 5178 点前两周）&quot;">​</a></h2><p><strong>核心论点</strong>：① 牛市是工具——拉高股价把国企股权&quot;卖一遍&quot;，为国企改革、注册制、金融开放铺路；② 8000 点不可能：要引外资接盘国企，估值须回国际标准，&quot;2000 点的时候，呵呵&quot;；③ 崩盘是主动选择：注册制出台前先把股市一跌到底，让股民恨旧制度，再把游资热钱&quot;永远套住&quot;为资本项目开放前减压，随后查黑庄平愤；④ 崩盘形态：没有买盘，两周内主板跌 1500 点，创业板可能指数跌停；⑤ 人民币&quot;稳定的慢慢下跌&quot;。</p><p><strong>方法论</strong>：从政府目标函数倒推政策与行情——&quot;只有等大多数人都不好过了，才会支持变革&quot;。 <strong>金句</strong>：我是 2013 年 1900 多点买的，4500 点以后全部清仓；股市能在你想不到的时候涨起来，就一定会在你最不经意的时候跌下去。 <strong>预测对照</strong>：两月内股灾→准（6 月千股跌停）；人民币稳步贬值→准（811 汇改）；崩盘换改革→部分准（注册制 2023 年才落地）；&quot;2016 新纪元慢牛&quot;→不准（2016 年初熔断）。</p><h2 id="_5-七剑战歌之风月《来经济论坛一看-这里怎么又被房多们占领了》-2018-3–11" tabindex="-1">5. 七剑战歌之风月《来经济论坛一看，这里怎么又被房多们占领了》（2018.3–11） <a class="header-anchor" href="#_5-七剑战歌之风月《来经济论坛一看-这里怎么又被房多们占领了》-2018-3–11" aria-label="Permalink to &quot;5. 七剑战歌之风月《来经济论坛一看，这里怎么又被房多们占领了》（2018.3–11）&quot;">​</a></h2><p><strong>核心论点</strong>：① 房价就是货币现象，货币收紧说什么都没用；② 2008–2017 十年靠借债发展，债务扩张停止＝增量资金消失＝收入与房价同坠；③ 美元加息+天量 M2→保汇率必须被动紧缩，&quot;房地产已经被抛弃&quot;；④ 拉美化警告：汇率崩溃消灭储蓄，再积累要 50–60 年；⑤ 去库存是伪命题：&quot;只要有价格刺激，库存永远也去不完&quot;；⑥ 预判二手房流动性锁死、房贷利率 6%、房产税立法、小银行出险、债务违约潮，房价跌回 2015 甚至 2008 年价位。</p><p><strong>方法论</strong>：盯 M2、利率、外储三组数据，用&quot;借钱发展—还债出清&quot;的资产负债表框架看全局。 <strong>金句</strong>：炒房子有好下场的国家，全世界还没有先例；财富不能永恒。 <strong>预测对照</strong>：房价 2018 年内崩至 2015 底→不准（2018–2021 还冲顶，普跌 2021 下半年才开始，成都 6000/平未发生）；房产税立法→不准（至今未落地）；M2 被动紧缩→不准（2020 疫情大放水，走向低利率债务置换）；违约潮、房企暴雷、二手房流动性陷阱→准（2021 年后兑现）；小银行出险→准（2019 包商被接管）。方向对、时点提前约三年。</p><h2 id="_6-海边的老王-王海滨-《赚未来十年的钱》-2009-4–2010-10" tabindex="-1">6. 海边的老王（王海滨）《赚未来十年的钱》（2009.4–2010.10） <a class="header-anchor" href="#_6-海边的老王-王海滨-《赚未来十年的钱》-2009-4–2010-10" aria-label="Permalink to &quot;6. 海边的老王（王海滨）《赚未来十年的钱》（2009.4–2010.10）&quot;">​</a></h2><blockquote><p>注：清单中《23-赚未来十年的钱-王海滨.pdf》与《23-【经济专栏】赚未来十年的钱【已出版】.pdf》为同一作品两个版本，前者是图片版无正文，本节以文字版为准，两篇合并。</p></blockquote><p><strong>核心论点</strong>：① 危机不是感冒是慢性病，&quot;未来的十年是一个动荡的慢性病过程&quot;；② 消费主体在体制内，&quot;只要公务员阶层收入不降低，对整体经济的打击就不会大&quot;；③ 印钱是必由之路→&quot;房地产业一定是不能衰败的&quot;，纸币泛滥时代房子是最稳的保值物；④ 财政 doom loop：财政收入降→地产衰→地方更靠卖地→加税→实体更弱；⑤ 房产保有税与土地财政的博弈：&quot;没有保有税，没有地产财政的终结&quot;；中国正与日本当年命运重叠；⑥ 主张开放私营经济、温州模式、放开户籍让大城市集聚；⑦ 个人策略：乱世买金、适当换美元、靠近体制是投资者&quot;正确的做法&quot;。</p><p><strong>方法论</strong>：生意人视角看利益流向——谁付账、谁受益；承认&quot;善变&quot;，随时按新信息修正。 <strong>金句</strong>：房价上涨是通胀的表象，不是因果关系；当你投资时，还是要势利一点。 <strong>预测对照</strong>：房地产十年不能衰败→准（2009–2021）；土地财政绑架地方→准；房产税替代土地财政→不准（十余年未落地）；与日本&quot;失去二十年&quot;重叠→部分准（2021 年后才显形）；黄金长期向上→准（2019–2025 大牛市）。</p><h2 id="_7-大文豪曼因斯坦《大神预言神准》-2016-10–2017-2" tabindex="-1">7. 大文豪曼因斯坦《大神预言神准》（2016.10–2017.2） <a class="header-anchor" href="#_7-大文豪曼因斯坦《大神预言神准》-2016-10–2017-2" aria-label="Permalink to &quot;7. 大文豪曼因斯坦《大神预言神准》（2016.10–2017.2）&quot;">​</a></h2><p><strong>核心论点</strong>：① 命门不是楼市是外储：外储从高峰降 1 万亿美元，石油粮食进口是硬需求；② 2016 年一线暴涨的真目的：用楼市把社会游资锁进一线房产堵住换汇——&quot;你想换美元？你没钱了&quot;，以大问题掩护生死问题，围棋弃大龙；③ 人民币锚＝外汇占款（基础货币 29 万亿中占 23.5 万亿），&quot;外储是因，房产是果&quot;；④ 已在通缩：15.6 万亿社融过半进庞氏借贷、7 月新增贷款 102% 是房贷，货币政策失效，&quot;钱快没了&quot;；⑤ 中国是世界工厂，只要外储不见底就不会恶性通胀；⑥ 2016 年 6 月一线楼市极值→年底政策转向→2017 全面着陆→跟随美元加息，&quot;这个周期钱会非常值钱，负债的人十分痛苦&quot;；⑦ 建议：不欠债、拿稳现金、分银行存款、别碰理财与 P2P。</p><p><strong>方法论</strong>：拆央行资产负债表与货币乘数，用外汇占款判&quot;放水还是救火&quot;；明斯基三阶段给债务定性。 <strong>金句</strong>：人人都觉得人民币要变草纸了，个个欠了一屁股债——最后手里有钱的人变成了稀缺资源；今年的房产是财富最后的直通车，其实这是一班地狱直通车。 <strong>预测对照</strong>：锁游资保外储→准（2017 外储企稳、管制强化）；紧缩周期→部分准（2017–2018 去杠杆，2018 底即转宽松）；P2P 全灭、理财爆雷→准；不恶性通胀→准（2023–2025 通缩压力）；2017 楼市全面着陆→不准（一线仅短暂回调，普跌 2021 年后才到）；美股历史大顶在一两个月→不准（随后又涨四年多）。</p><h2 id="_8-yyttff1981《财经时事-各抒己见》-2018-9–2019-2" tabindex="-1">8. yyttff1981《财经时事 各抒己见》（2018.9–2019.2） <a class="header-anchor" href="#_8-yyttff1981《财经时事-各抒己见》-2018-9–2019-2" aria-label="Permalink to &quot;8. yyttff1981《财经时事 各抒己见》（2018.9–2019.2）&quot;">​</a></h2><p>新闻摘编+短评帖，楼主立场：① &quot;对于房地产未来 3 年，全行业坚决看空&quot;；棚改撤退后无人口支撑的三四五线城市&quot;10 年都未必会恢复&quot;；② 2017 年家庭债务/GDP 达 49.1% 历史新高，将压制长期消费；③ &quot;国家之间的竞争，是货币纪律的竞争，比的是谁在发行货币方面更有节操&quot;；④ 万科喊&quot;活下去&quot;不是作秀：&quot;再来一次四万亿已无可能&quot;；⑤ 转引存款分布：约 50 万亿存款在 1 千万人手里、10 亿人人均约 8000 元。 <strong>预测对照</strong>：地产三年看空→部分准（2021 年后兑现）；家庭债务压制消费→准（2019 年后消费持续疲弱）；&quot;不会再有四万亿&quot;→准（2020 年刺激路径完全不同）。</p><h2 id="_9-黄汉升-1《老黄第六季——证券市场与公司研究》-2014-2–2019-3" tabindex="-1">9. 黄汉升 1《老黄第六季——证券市场与公司研究》（2014.2–2019.3） <a class="header-anchor" href="#_9-黄汉升-1《老黄第六季——证券市场与公司研究》-2014-2–2019-3" aria-label="Permalink to &quot;9. 黄汉升 1《老黄第六季——证券市场与公司研究》（2014.2–2019.3）&quot;">​</a></h2><p><strong>核心论点</strong>：① 2014 年开帖即判断小市值新经济（电子、互联网、机器人、生物医药）是结构性主线，亲历 2014–2015 杠杆牛；② &quot;中国要提高证券化比例，未来要把金融风险向屁民们充分转移了&quot;（2014.11）；③ 2018 年定性：&quot;金融去杠杆……是除了 05 年 998 以外最可怕的熊，吃人不眨眼&quot;；④ 个股框架＝业绩+估值+资本运作+概念弹性；京东方案例&quot;先圈地（营收）再提价&quot;，一年眼光看不到国产替代格局；⑤ 2019 年判断流动性回暖但基本面有雷，科创板将大幅提升科技股估值。</p><p><strong>方法论</strong>：量化模型选股+仓位对冲+严控回撤的实战派，每天公开操作；把政策映射到行业估值。 <strong>预测对照</strong>：2014 牛市启动→准；金融风险向居民转移→准（2015–2021 居民杠杆翻倍）；2018 大熊→准（沪指全年跌 24.6%）；京东方/国产替代→准（2019–2021 面板与半导体行情）。</p><h2 id="_10-螺蛳及顶伟大少《剖析国有银行基层经营-管窥中国金融乱象》-2011-4–2018-2" tabindex="-1">10. 螺蛳及顶伟大少《剖析国有银行基层经营，管窥中国金融乱象》（2011.4–2018.2） <a class="header-anchor" href="#_10-螺蛳及顶伟大少《剖析国有银行基层经营-管窥中国金融乱象》-2011-4–2018-2" aria-label="Permalink to &quot;10. 螺蛳及顶伟大少《剖析国有银行基层经营，管窥中国金融乱象》（2011.4–2018.2）&quot;">​</a></h2><p><strong>核心论点</strong>（国有大行市级分行内部人视角）：① &quot;变通&quot;文化：发票科目串用，&quot;帐无实帐，数无实数&quot;；② 利润转型神话：中间业务收入≈贷款客户被强收的服务费，且提前入帐、预收、假入帐；③ 真实贷款价格＝基准上浮 40–50%+各类收费与派生存款，中小实体融资贵是制度产物；④ 借壳贷款、假报表、抵押品高估，信贷资金流向限控行业；⑤ &quot;朱时代是乱但真，现在是乱且假&quot;，风控系于&quot;一把手文化&quot;；⑥ &quot;风险不会凭空消失，经济更不会因为放水和转贷展期而起死回生&quot;；&quot;从清理乱收费解决融资难，本来就是个世纪大笑话&quot;——收费停了利率必上浮；⑦ 后期反思：公司信贷数据失真，&quot;任何以数据为立论基础的经济分析都是扯蛋&quot;，要研究&quot;经济政策与民众行为的心理博弈&quot;。</p><p><strong>方法论</strong>：内部审计视角列出可验证的造假手法，把微观乱象上升为宏观数据可信度问题。 <strong>金句</strong>：银行每个细胞都能健康运营，才谈得上金融健康；假冒伪劣一直在挽救着吾国经济。 <strong>预测对照</strong>：乱象整治无效、收费变形复活→准；风险靠展期不消失→准（2013 钢贸崩盘、风险层层延期至房企与城投）；房地产&quot;回光返照&quot;→准（2012–13、2015–16 两轮）；数据失真→准（此后财政挤水分、资产质量争议不断）。</p><h2 id="_11-不要二分法《百年未有之大变局-世界将走向何方-》-2019-6–12" tabindex="-1">11. 不要二分法《百年未有之大变局，世界将走向何方？》（2019.6–12） <a class="header-anchor" href="#_11-不要二分法《百年未有之大变局-世界将走向何方-》-2019-6–12" aria-label="Permalink to &quot;11. 不要二分法《百年未有之大变局，世界将走向何方？》（2019.6–12）&quot;">​</a></h2><p><strong>核心论点</strong>：① 霸权木桶理论：帝国霸权由工业、科技、金融、军事、文化五块木板构成，&quot;有一块先漏，整个木桶的水都会流光&quot;——西班牙先漏金融、英国先漏工业、苏联先漏文化，美国先漏工业；② 贸易战＝英国&quot;帝国特惠制&quot;翻版：主导国衰落期的保护挣扎，且美国对 36 国同时开火，不只针对中国；③ 大国没资格投降：俄罗斯投降也没被接纳；④ 美国症结是分配：GDP 增 70% 而家庭中位数收入不增，中产占比从 80% 跌到 49%；⑤ 5G 之战胜负在路线：通信是基础设施而非生意；⑥ 高通税：中国手机厂商出货全球一半、只分 6% 利润，专利壁垒决定利润分配；⑦ 舆论战：&quot;文章是子弹，技术平台才是武器&quot;。</p><p><strong>方法论</strong>：长周期霸权兴衰类比+产业数据对标，自下而上拆行业验证宏观判断。 <strong>预测对照</strong>：中美对抗长期化→准（科技战层层加码）；美国补工业短板→部分准（回流有限，但 2022 年后芯片法案确在补）；5G 中国领先→部分准（商用领先，高端芯片被制裁反噬）。</p><h2 id="_12-总览与心得-这批帖子的共同经济框架" tabindex="-1">12. 总览与心得：这批帖子的共同经济框架 <a class="header-anchor" href="#_12-总览与心得-这批帖子的共同经济框架" aria-label="Permalink to &quot;12. 总览与心得：这批帖子的共同经济框架&quot;">​</a></h2><p><strong>（1）货币蓄水池是理解 2000–2021 年中国的钥匙。</strong> flp713 最早系统化：超发的钱必须有池子——民生市场化（94–2000）→股市房市（2000–2011）→土地与国际化（2011–2020）；第三元、曼因斯坦接着推演：地产饱和后想切到股市（注册制＝把赌场变印钞厂），失败后再用房市锁流动性保外储。15 年检验：蓄水池—锁流动性—腾挪时间这条主线几乎逐格应验（2015 股灾、2016 抢房、2017 外储企稳）。</p><p><strong>（2）人民币的锚是外储与美元，不是印钞机。</strong> &quot;外储是因，房产是果&quot;（曼因斯坦）、&quot;扭曲汇率→被动发钞&quot;（flp713）、&quot;人民币最后贬值&quot;（第三元）互相印证。2015–2017 的贬值与资本管制验证&quot;外储是命门&quot;；但&quot;贬值窗口永久关闭&quot;与&quot;国际化很快&quot;两个极端都没兑现——现实是管制下缓慢走弱、份额缓慢爬升。</p><p><strong>（3）2014 年后：从&quot;印钞—通胀&quot;切换到&quot;债务—通缩&quot;叙事。</strong> &quot;庞氏借贷+货币政策失效&quot;（曼因斯坦）、&quot;增量资金消失&quot;（七剑）、&quot;现实升值名义贬值&quot;（第三元）指向同一结论：放水不再变成物价，而是变成债务滚动。以 2026 年回望，这是全部帖子里最经得起检验的判断——2021 年后楼市下行、2023 年后 CPI 在零附近徘徊，通缩派赢了通胀派。</p><p><strong>（4）财政—土地—体制内消费的闭环。</strong> 王海滨的&quot;财政降→地产衰→加税→实体弱&quot;与螺蛳大少银行内部的微观证据互为表里，源头是 flp713 的分配失衡论；解释了 2021 年后土地财政坍塌。</p><p><strong>（5）失效的部分同样有教益。</strong> ① 长期两位数通胀论错了，通缩比通胀先来；② &quot;立即崩盘&quot;的时间点集体偏早（七剑 2018、曼因斯坦 2017、kulese 的 2016 慢牛），趋势对、时点错，照做会在黎明前离场；③ 房产税、土改释放宅基地、人民币国际化三类&quot;制度性大杀器&quot;全部比预期慢一个数量级——天涯财经帖的系统性偏差：高估政策速度，低估路径依赖。</p><p><strong>（6）可复用的三件工具</strong>：读文件倒推十年布局（flp713）；拆央行资产负债表看&quot;放水还是救火&quot;（曼因斯坦）；从利益流向而非供需叙事判断资产价格（kulese、王海滨、螺蛳大少）。三套独立方法在 2015、2016 两个关键节点上交叉验证——方法互证，胜过任何单一预测。</p>',41)])])}const _=o(a,[["render",n]]);export{h as __pageData,_ as default};
